(function(){
  "use strict";

  var STORAGE_KEY = "eic_companion";
  var SEEN_PREFIX = "eic_companion_seen_";

  var NAMES = {strategist:"The Strategist", closer:"The Closer", mentor:"The Mentor", analyst:"The Analyst"};
  var ACCENTS = {strategist:"#3B7FD9", closer:"#E8621A", mentor:"#C99A2E", analyst:"#6D5FE0"};
  var ICONS = {
    strategist: '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 3v2M12 19v2M3 12h2M19 12h2"/><path d="M15 9l-2.5 5.5L9 17l2.5-5.5z"/></svg>',
    closer: '<svg viewBox="0 0 24 24"><path d="M13 2L4.5 14h5.5l-1 8L19 10h-5.5z"/></svg>',
    mentor: '<svg viewBox="0 0 24 24"><path d="M4 5v15a2 2 0 002-2V5"/><path d="M4 5a2 2 0 012-2h6v17H6a2 2 0 01-2-2"/><path d="M20 5v15a2 2 0 01-2-2V5"/><path d="M20 5a2 2 0 00-2-2h-6v17h6a2 2 0 002-2"/></svg>',
    analyst: '<svg viewBox="0 0 24 24"><path d="M3 3v18h18"/><path d="M7 15l4-4 3 3 5-6"/></svg>'
  };
  var TYPE_LABELS = {tip:"Tip", reflection:"Think about it", nudge:"Vocabulary", luck:"Before you start", welcome:"Companion"};
  var PHOTOS = {
    strategist: "data:image/jpeg;base64,",
    closer: "data:image/jpeg;base64,",
    mentor: "data:image/jpeg;base64,",
    analyst: "data:image/jpeg;base64,"
  };

  var STYLE_ID = "eic-companion-style";
  var CONTAINER_ID = "eic-companion-container";

  function injectStyles(){
    if (document.getElementById(STYLE_ID)) return;
    var css = '';
    css += '#' + CONTAINER_ID + '{position:fixed;bottom:24px;right:24px;z-index:9999;max-width:420px;font-family:Inter,sans-serif}';
    css += '.eic-comp-card{display:flex;gap:14px;align-items:flex-start;background:#0d1a30;border:1px solid rgba(255,255,255,.1);';
    css += 'border-radius:18px;padding:18px 20px;box-shadow:0 14px 36px rgba(0,0,0,.45);opacity:0;transform:translateY(12px);';
    css += 'transition:opacity .25s ease,transform .25s ease}';
    css += '.eic-comp-card.visible{opacity:1;transform:translateY(0)}';
    css += '.eic-comp-badge{width:48px;height:48px;border-radius:50%;position:relative;flex-shrink:0}';
    css += '.eic-comp-badge img{width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;border:3px solid var(--eic-accent)}';
    css += '.eic-comp-badge .eic-comp-icon{position:absolute;bottom:-2px;right:-2px;width:18px;height:18px;border-radius:50%;';
    css += 'background:var(--eic-accent);display:flex;align-items:center;justify-content:center;border:2px solid #0d1a30}';
    css += '.eic-comp-badge .eic-comp-icon svg{width:9px;height:9px;stroke:#fff;fill:none;stroke-width:2.6}';
    css += '.eic-comp-body{flex:1;padding-top:2px}';
    css += '.eic-comp-type{font-size:9.5px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:var(--eic-accent);margin-bottom:6px}';
    css += '.eic-comp-text{font-size:14px;line-height:1.6;color:rgba(255,255,255,.92)}';
    css += '.eic-comp-close{background:none;border:none;color:rgba(255,255,255,.35);cursor:pointer;font-size:18px;line-height:1;padding:0 0 0 8px;flex-shrink:0}';
    css += '.eic-comp-close:hover{color:#fff}';
    css += '@media(max-width:640px){#' + CONTAINER_ID + '{left:16px;right:16px;bottom:16px;max-width:none}}';
    var tag = document.createElement("style");
    tag.id = STYLE_ID;
    tag.textContent = css;
    document.head.appendChild(tag);
  }

  function ensureContainer(){
    var el = document.getElementById(CONTAINER_ID);
    if (!el) {
      el = document.createElement("div");
      el.id = CONTAINER_ID;
      document.body.appendChild(el);
    }
    return el;
  }

  function getAvatar(){
    try { return localStorage.getItem(STORAGE_KEY); } catch(e) { return null; }
  }

  function hasSeen(id){
    try { return localStorage.getItem(SEEN_PREFIX + id) === "1"; } catch(e) { return false; }
  }

  function markSeen(id){
    try { localStorage.setItem(SEEN_PREFIX + id, "1"); } catch(e) {}
  }

  function show(opts){
    opts = opts || {};
    var avatar = getAvatar();
    if (!avatar || !PHOTOS[avatar]) return;
    if (opts.id && !opts.force && hasSeen(opts.id)) return;

    injectStyles();
    var container = ensureContainer();

    var card = document.createElement("div");
    card.className = "eic-comp-card";
    card.style.setProperty("--eic-accent", ACCENTS[avatar]);

    var typeLabel = TYPE_LABELS[opts.type] || "Companion";

    card.innerHTML =
      '<div class="eic-comp-badge">' +
        '<img src="' + PHOTOS[avatar] + '" alt="' + NAMES[avatar] + '">' +
        '<div class="eic-comp-icon">' + ICONS[avatar] + '</div>' +
      '</div>' +
      '<div class="eic-comp-body">' +
        '<div class="eic-comp-type">' + typeLabel + '</div>' +
        '<div class="eic-comp-text"></div>' +
      '</div>' +
      '<button class="eic-comp-close" aria-label="Dismiss">&times;</button>';

    card.querySelector(".eic-comp-text").textContent = opts.message || "";
    container.appendChild(card);

    requestAnimationFrame(function(){ card.classList.add("visible"); });

    function dismiss(){
      card.classList.remove("visible");
      setTimeout(function(){ card.remove(); }, 260);
    }

    card.querySelector(".eic-comp-close").addEventListener("click", dismiss);
    var autoDismiss = setTimeout(dismiss, opts.duration || 9000);
    card.addEventListener("mouseenter", function(){ clearTimeout(autoDismiss); });

    if (opts.id) markSeen(opts.id);
  }

  window.Companion = {
    show: show,
    getAvatar: getAvatar
  };
})();
